using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using APIShared;
using APIShared.ModSettings;
using MessagePack;
using SHCDESE.API;
using Spectator.LordOverview;
using Spectator;
internal static class OverviewPresetTests {
 static int checks;
 static void Check(bool condition,string message){checks++;if(!condition)throw new Exception(message);}
 static SpectatorViewModel Prepare(string file){var model=new SpectatorViewModel();model.PreparePresets(null,file,"LordOverviewPresets");model.ActivatePresets();return model;}
 public static int Run(string[] args){try{
  string root=args[0];Program.PresetFixtureInstallRoot=Path.Combine(root,"installation");Directory.CreateDirectory(Program.PresetFixtureInstallRoot);
  PersonalSettingsPaths.TestDocumentsDirectory=_=>Path.Combine(root,"documents");
  APIShared.Localization.UiText.Configure(()=>"en-US");GameNetworkAPI.LocalHost=true;GameNetworkAPI.Networked=true;GameNetworkAPI.MultiplayerGame=true;
  string file=Path.Combine(Program.PresetFixtureInstallRoot,"Spectator.LordOverview.dll");var model=Prepare(file);
  Check(!model.AllowEnemyDetails && model.EnableMod && model.OverviewShowEliminated,"safe code defaults preserve existing eliminated rows");
  Check(!model.Overview.ShowWhileHudHidden,"keeping the scoreboard during Hide HUD is opt-in");
  Check(!model.ShowDateWhenHudHidden,"showing the date during Hide HUD is opt-in");
  Check(model.OverviewColumns=="GreatestLord,Gold,Army,TroopsKilled,Popularity","fresh settings use the requested five default values in order");
  model.Overview.SetDisplayColumns("Gold,Army,Popularity,Fear");Check(Prepare(file).OverviewColumns=="Gold,Army,Popularity,Fear","even the old exact default selection is preserved when stored");
  model.Overview.SetDisplayShowEliminated(false);Check(!Prepare(file).OverviewShowEliminated,"local eliminated-player filter survives restart");
  model.Overview.SetDisplayShowEliminated(true);
  model.Overview.SetDisplayColumns("Fear,Gold,TroopsKilled");model.Overview.SetDisplayColumns("TroopsKilled,Gold,Fear");model.AllowEnemyDetails=true;
  var restart=Prepare(file);Check(restart.OverviewColumns=="TroopsKilled,Gold,Fear" && restart.AllowEnemyDetails,"actual shared storage survives restart and replacement");
  GameNetworkAPI.LocalHost=false;restart.System_RefreshSettingsAccess();restart.AllowEnemyDetails=false;Check(restart.AllowEnemyDetails,"client rejected host edit");
  restart.ShowDateWhenHudHidden=true;
  Check(Prepare(file).ShowDateWhenHudHidden,"client HUD date preference survives restart");
  restart.Overview.SetDisplayColumns("Gold,Popularity");Check(restart.OverviewColumns=="Gold,Popularity","client local columns remain editable");
  restart.Overview.ObserveLobby(new LobbyStateSnapshot(10,null,false,2,false,null,null));
  Check(!restart.Overview.EnemyDetailsReceived,"personal host preference is not host confirmation");
  GameXAMLManagerAPI.Instance.ApplyNetworkSync(restart,()=>restart.AllowEnemyDetails=true);
  Check(restart.Overview.EnemyDetailsReceived && restart.AllowEnemyDetails,"same-value authoritative update confirms permission");
  Check(restart.OverviewColumns=="Gold,Popularity","host update preserves local columns");
  Check(restart.ShowDateWhenHudHidden,"host update preserves the local HUD date preference");
  restart.Overview.ObserveLobby(new LobbyStateSnapshot(null,null,false,2,true,null,null));Check(restart.Overview.EnemyDetailsReceived,"map transition retains confirmed lobby permission");
  restart.Overview.ObserveLobby(new LobbyStateSnapshot(11,null,false,2,false,null,null));Check(!restart.Overview.EnemyDetailsReceived,"new lobby discards old permission");
  GameXAMLManagerAPI.Instance.ApplyNetworkSync(restart,()=>restart.AllowEnemyDetails=true);
  restart.Overview.ObserveLobby(new LobbyStateSnapshot(11,null,true,0,false,"Unresolved authority",null));Check(!restart.Overview.EnemyDetailsReceived,"invalid lobby observation revokes confirmation");
  var disk=Prepare(file);Check(disk.AllowEnemyDetails,"received host state did not replace personal host preference");
  GameXAMLManagerAPI.Instance.ApplyNetworkSync(restart,()=>restart.AllowEnemyDetails=false);Check(!restart.AllowEnemyDetails,"host can revoke permission");
  Check(Prepare(file).AllowEnemyDetails,"host revocation not persisted into local preference");
  GameNetworkAPI.LocalHost=true;model.System_RefreshSettingsAccess();
  model.System_EnterMissionPreset(new Dictionary<string,byte[]>{{nameof(SpectatorViewModel.AllowEnemyDetails),MessagePackSerializer.Serialize(false)}},"Trail",false);
  model.Overview.SetDisplayColumns("Fear,Popularity");Check(model.Overview.DisplayColumns=="Fear,Popularity","locked mission still permits runtime display choice");
  model.Overview.SetDisplayShowEliminated(false);Check(!model.Overview.DisplayShowEliminated && !model.OverviewShowEliminated && !Prepare(file).OverviewShowEliminated,"locked mission persists local player filter immediately");
  model.Overview.SetShowWhileHudHidden(true);
  Check(model.Overview.ShowWhileHudHidden && Prepare(file).Overview.ShowWhileHudHidden,"locked mission persists the local HUD preference immediately");
  model.System_ExitMissionPreset();Check(model.OverviewColumns=="Fear,Popularity","pending display choice persists through normal source after mission");
  Check(Prepare(file).OverviewColumns=="Fear,Popularity","deferred local choice survives restart");
  Check(!Prepare(file).OverviewShowEliminated,"deferred player filter persists after source exit");
  var reorder=new ColumnSelection();reorder.Load(model.OverviewColumns);Check(reorder.MoveTo(Metric.Popularity,0),"header drop changes selection by metric ID");
  model.Overview.SetDisplayColumns(Metrics.Serialize(reorder.Columns));Check(Prepare(file).OverviewColumns=="Popularity,Fear","header-drop order survives actual shared persistence restart");
  model.OverviewColumns="Gold,Army,Popularity,Fear,GoldAcquired,MaxPopulation";Check(model.OverviewColumns=="Gold,Army,Popularity,Fear,GoldAcquired,MaxPopulation","more than five columns persist without normalization");
  model.OverviewColumns="Gold,other.mod/missing,Army";Check(Prepare(file).OverviewColumns==model.OverviewColumns,"missing external provider survives actual preset restart");
    model.OverviewDesign="Cards";model.OverviewLordGrid="Rows:3";model.OverviewValueGrid="Columns:4";
  var layoutRestart=Prepare(file);Check(layoutRestart.OverviewDesign=="Cards" && layoutRestart.OverviewLordGrid=="Rows:3" && layoutRestart.OverviewValueGrid=="Columns:4","design and both grid preferences survive actual shared persistence");
  model.System_EnterMissionPreset(new Dictionary<string,byte[]>{{nameof(SpectatorViewModel.AllowEnemyDetails),MessagePackSerializer.Serialize(false)}},"Trail",false);
  model.Overview.SetDisplayDesign(OverviewDesign.SplitList);model.Overview.SetDisplayGrid(true,new GridFlow(1,8));model.Overview.SetDisplayGrid(false,new GridFlow(2,3));
  Check(model.Overview.DisplayDesign==OverviewDesign.SplitList && model.Overview.DisplayLordGrid.ToString()=="1x8" && model.Overview.DisplayValueGrid.ToString()=="2x3","locked mission permits all local runtime layout choices");
  model.System_ExitMissionPreset();layoutRestart=Prepare(file);
  Check(layoutRestart.OverviewDesign=="SplitList" && layoutRestart.OverviewLordGrid=="1x8" && layoutRestart.OverviewValueGrid=="2x3","deferred layout choices survive source exit and restart");
  GameNetworkAPI.LocalHost=false;layoutRestart.System_RefreshSettingsAccess();layoutRestart.Overview.SetDisplayDesign(OverviewDesign.Cards);
  Check(layoutRestart.OverviewDesign=="Cards","client can change its local design");
  GameXAMLManagerAPI.Instance.ApplyNetworkSync(layoutRestart,()=>layoutRestart.AllowEnemyDetails=false);
  Check(!layoutRestart.OverviewShowEliminated,"host sync cannot replace a local player filter");
  Check(layoutRestart.OverviewDesign=="Cards" && layoutRestart.OverviewLordGrid=="1x8","incoming host preferences preserve local layouts");
  layoutRestart.Overview.SetDisplayGrid(true,GridFlow.Parse("Rows:3",2).Normalize(8));
  layoutRestart.Overview.SetDisplayGrid(false,GridFlow.Parse("Columns:4",3).Normalize(7));
  var migrated=Prepare(file);Check(migrated.OverviewLordGrid=="3x3" && migrated.OverviewValueGrid=="2x4","legacy preferences migrate and persist as exact grid pairs");
  migrated.Overview.SetDisplayGrid(false,migrated.Overview.DisplayValueGrid.Normalize(11));Check(Prepare(file).OverviewValueGrid=="3x4","expanded grid persists without dropping new values");
  layoutRestart.OverviewDesign="garbage";layoutRestart.OverviewLordGrid="Rows:-3";layoutRestart.OverviewValueGrid="Columns:0";
  Check(layoutRestart.OverviewDesign=="List" && layoutRestart.OverviewLordGrid=="Columns:2" && layoutRestart.OverviewValueGrid=="Columns:3","invalid persisted preferences normalize safely");
  migrated.Overview.SetDisplayColumns("GreatestLord,Gold");Check(Prepare(file).OverviewColumns=="GreatestLord,Gold","new score selection and order survive local storage restart");
  migrated.System_EnterMissionPreset(new Dictionary<string,byte[]>{{nameof(SpectatorViewModel.AllowEnemyDetails),MessagePackSerializer.Serialize(false)}},"Trail",false);
  migrated.Overview.SetDisplayColumns("Gold,GreatestLord");Check(migrated.Overview.DisplayColumns=="Gold,GreatestLord","score selection stages under a locked mission source");
  migrated.System_ExitMissionPreset();Check(Prepare(file).OverviewColumns=="Gold,GreatestLord","staged score selection persists after mission exit");
  migrated.ResetToDefaultCommand.Execute(null);Check(migrated.OverviewColumns=="GreatestLord,Gold,Army,TroopsKilled,Popularity" && Prepare(file).OverviewColumns==migrated.OverviewColumns,"explicit reset applies and persists the new defaults");
  migrated.Overview.SetDisplayColumns("Gold,GreatestLord");
  migrated.Overview.SetDisplaySort("GreatestLord",true);
  var sortedRestart=Prepare(file);Check(sortedRestart.OverviewSortBy=="GreatestLord" && sortedRestart.OverviewSortDescending,"sort identity and direction persist with the real preset controller");
  migrated.System_EnterMissionPreset(new Dictionary<string,byte[]>(),"Savegame",false);
  migrated.Overview.SetDisplaySort("Gold",false);
  Check(migrated.Overview.DisplaySortBy=="Gold" && migrated.OverviewSortBy=="Gold" && Prepare(file).OverviewSortBy=="Gold","locked source persists personal sort immediately");
  migrated.System_ExitMissionPreset();
  Check(Prepare(file).OverviewSortBy=="Gold" && !Prepare(file).OverviewSortDescending,"pending sort survives source exit and restart");
  migrated.System_EnterMissionPreset(new Dictionary<string,byte[]>(),"Map",true);
  migrated.Overview.SetDisplayDesign(OverviewDesign.Cards);
  Check(migrated.Overview.DisplayDesign==OverviewDesign.Cards,"editable temporary drafts retain personal UI intent too");
  migrated.System_ExitMissionPreset();
  Check(Prepare(file).OverviewDesign=="Cards","temporary draft cannot swallow pending personal preferences");
  migrated.System_EnterMissionPreset(new Dictionary<string,byte[]>(),"Savegame",false);
  migrated.Overview.SetDisplayColumns("Fear,Gold");migrated.System_ExitMissionPreset();
  migrated.ResetToDefaultCommand.Execute(null);
  Check(migrated.Overview.DisplayColumns==Metrics.Serialize(Metrics.Defaults),"explicit personal reset wins over previously queued preferences");
  Console.WriteLine("PASS: "+checks+" production LordOverview settings/persistence/host-source checks.");return 0;
 }catch(Exception error){Console.Error.WriteLine(error);return 1;}}
}
